160	        }
161	        // The household id is deterministic from (lastName, postcode), so owners sharing a last name
162	        // and postcode are automatically the same household. It no longer gates duplicate detection
163	        // (that is the identity key alone) but still drives household-derived fields.
164	        owner.setHouseholdId(this.clinicService.householdIdFor(owner.getLastName(), owner.getPostcode()));
165	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
166	        // Duplicate detection is the single identity key: reject only when the new owner's whole
