282	                ? owner.getRegistrationDate()
283	                : LocalDate.now();
284	            owner.setRegistrationDate(toBusinessDay(effectiveDate));
285	            if (owner.getHouseholdId() == null) {
286	                owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
287	            }
288	            if (owner.getMemberId() == null) {
289	                owner.setMemberId(generateMemberId(owner));
290	            }
291	            if (owner.getNamesakeCount() == null) {
292	                owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
293	            }
294	            if (owner.getPossibleDuplicate() == null) {
295	                // A declared household member is not a suspected duplicate; otherwise flag it against
296	                // any existing member of the same household it collides with.
297	                Integer possibleDuplicateOf = declaredHouseholdMember ? null : findPossibleDuplicateOf(owner);
298	                owner.setPossibleDuplicateOf(possibleDuplicateOf);
299	                owner.setPossibleDuplicate(possibleDuplicateOf != null);
300	            }
301	            if (owner.getMembershipLevelCap() == null) {
302	                owner.setMembershipLevelCap(computeMembershipLevelCap(owner));
303	            }
304	        }
305	        ownerRepository.save(owner);
306	        decorateWithHouseholdMemberCount(owner);
307	    }
308	
309	    /**
310	     * Count the existing owners (before this create) that share the given first and last name,
311	     * compared case-insensitively, as required by the read-only {@code namesakeCount} field.
312	     */
313	    private int countNamesakes(String firstName, String lastName) {
314	        if (firstName == null || lastName == null) {
315	            return 0;
316	        }
317	        return (int) ownerRepository.findAll().stream()
318	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
319	                && lastName.equalsIgnoreCase(owner.getLastName()))
320	            .count();
321	    }
322	
323	    /**
324	     * Build a version-2 member id formatted {@code '<REGION><FY><HASH8><CHK>'}, where {@code REGION}
325	     * is the version-2 region code: the plain canonical region derived from the owner's postcode
326	     * (falling back to the city-to-region table, then {@code 'UNKNOWN'}, as resolved by
327	     * {@link LocalityResolver}) with the fixed {@code 'V2'} version tag appended (e.g.
328	     * {@code 'NSW' -> 'NSWV2'}), {@code FY} is the two-digit fiscal year (the fiscal year starting
329	     * on 1 July) of the business-day-adjusted registration date, {@code HASH8} is the first 8
330	     * upper-case hexadecimal characters of the SHA-256 digest over the owner's normalized telephone
331	     * concatenated with the last name, and {@code CHK} is a single Luhn check digit computed over
332	     * the digits of {@code <REGION><FY><HASH8>} (e.g. {@code 'NSWV2261A2B3C4D0'}).
333	     * <p>
334	     * The {@code 'V2'} version tag lives only inside this identifier, so the plain region it was
335	     * derived from still surfaces unchanged as the user-facing {@code locality}. Because the region
336	     * segment always carries the {@code 'V2'} tag, no version-1 member id is ever produced again.
337	     * <p>
338	     * If the computed id collides with an existing owner's {@code memberId}, it is de-duplicated
339	     * by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it unique
340	     * (e.g. {@code 'NSWV2261A2B3C4D0-2'}).
341	     */
342	    private String generateMemberId(Owner owner) {
343	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
344	        String regionV2 = region + Owner.IDENTITY_VERSION_TAG;
345	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
346	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
347	        String fiscalYear = String.format("%02d", FiscalYear.startYear(owner.getRegistrationDate()) % 100);
348	        String body = regionV2 + fiscalYear + Sha256Hex.upperHexPrefix(telephone + lastName, 8);
349	        String base = body + LuhnCheckDigit.compute(body);
350	
351	        Set<String> existingIds = ownerRepository.findAll().stream()
352	            .map(Owner::getMemberId)
353	            .filter(Objects::nonNull)
354	            .collect(Collectors.toSet());
355	        if (!existingIds.contains(base)) {
356	            return base;
357	        }
358	        int n = 2;
359	        while (existingIds.contains(base + "-" + n)) {
360	            n++;
361	        }
362	        return base + "-" + n;
363	    }
364	
365	    /**
366	     * Count the existing owners whose city matches the given city, compared case-insensitively,
367	     * used by the per-city capacity rule ({@link #isCityAtCapacity}).
368	     */
369	    private long countOwnersInCity(String city) {
370	        if (city == null) {
371	            return 0L;
372	        }
373	        return ownerRepository.findAll().stream()
374	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
375	            .count();
376	    }
377	
378	    @Override
379	    @Transactional(readOnly = true)
380	    public boolean isCityAtCapacity(String city) throws DataAccessException {
381	        return countOwnersInCity(city) >= CITY_CAPACITY;
382	    }
383	
384	    @Override
385	    @Transactional(readOnly = true)
386	    public boolean isCityApproachingCapacity(String city) throws DataAccessException {
387	        long count = countOwnersInCity(city);
388	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_CAPACITY;
389	    }
390	
391	    @Override
392	    @Transactional(readOnly = true)
393	    public boolean isCityOverSoftCapacity(String city) throws DataAccessException {
394	        return countOwnersInCity(city) >= CITY_CAPACITY_WARNING_THRESHOLD;
395	    }
396	
397	    @Override
398	    @Transactional(readOnly = true)
399	    public boolean isDailyRegistrationAtCapacity() throws DataAccessException {
400	        return countRegisteredToday() >= DAILY_CAPACITY;
401	    }
402	
403	    @Override
404	    @Transactional(readOnly = true)
405	    public boolean isBulkSignupDay() throws DataAccessException {
406	        return countRegisteredToday() > BULK_SIGNUP_THRESHOLD;
407	    }
408	
409	    /**
410	     * Count the owners whose registration date equals today's business day, used by the
411	     * daily create-limit and bulk-signup rules.
412	     */
413	    private long countRegisteredToday() {
414	        LocalDate businessDay = toBusinessDay(LocalDate.now());
415	        return ownerRepository.findAll().stream()
416	            .filter(owner -> businessDay.equals(owner.getRegistrationDate()))
417	            .count();
418	    }
419	
420	    /**
421	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
422	     * holiday is advanced one day at a time until a non-holiday weekday is reached, while a plain
423	     * weekday is returned unchanged. Applied to the effective registration date (whether supplied
424	     * or defaulted to the server date) so that the stored {@code registrationDate}, every value
425	     * derived from it (such as the member id's fiscal-year segment) and the per-day create-limit
426	     * all use the adjusted business day.
427	     */
428	    private static LocalDate toBusinessDay(LocalDate date) {
429	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
430	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
431	            || HOLIDAYS.contains(date)) {
432	            date = date.plusDays(1);
433	        }
434	        return date;
435	    }
436	
437	    @Override
438	    @Transactional(readOnly = true)
439	    public boolean isIdentityKeyInUse(Owner owner) throws DataAccessException {
440	        String identityKey = owner.getIdentityKey();
441	        return ownerRepository.findAll().stream()
442	            .filter(existing -> existing != owner)
443	            .filter(existing -> !existing.isDeleted())
444	            .map(Owner::getIdentityKey)
445	            .anyMatch(identityKey::equals);
446	    }
447	
448	    /**
449	     * Resolve the id of an existing owner that the given (not yet persisted) owner is a <em>possible</em>
450	     * duplicate of, or {@code null} when there is none. A possible duplicate has a <em>different</em>
451	     * identity key from the existing owner (so it is not a hard duplicate) yet shares the Soundex code
452	     * of its last name and the same postcode, so it is worth flagging as a soft match. When several
453	     * existing owners match, the one with the lowest id is returned so the result is deterministic.
454	     * Computed once, at creation, to drive the read-only {@code possibleDuplicate}/
455	     * {@code possibleDuplicateOf} fields.
456	     */
457	    private Integer findPossibleDuplicateOf(Owner owner) {
458	        String identityKey = owner.getIdentityKey();
459	        String lastNameSoundex = Soundex.encode(owner.getLastName());
460	        String postcode = owner.getPostcode();
461	        return ownerRepository.findAll().stream()
462	            .filter(existing -> existing != owner && existing.getId() != null)
463	            .filter(existing -> !existing.isDeleted())
464	            .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
465	            .filter(existing -> lastNameSoundex.equals(Soundex.encode(existing.getLastName())))
466	            .filter(existing -> Objects.equals(postcode, existing.getPostcode()))
467	            .map(Owner::getId)
468	            .min(Integer::compareTo)
469	            .orElse(null);
470	    }
471	
472	    /**
473	     * Compute the membership-level ceiling for a new owner, as required by the level-cap rule: a new
474	     * owner's {@code membershipLevel} cannot exceed one above the current maximum membership level
475	     * among its household members (existing owners sharing the same {@code householdId}, excluding
476	     * soft-deleted ones and the owner itself). Returns one above that maximum, or {@code null} when
477	     * the owner has no household id or no existing household member, in which case no cap applies.
478	     *
479	     * <p>Each existing member's level is read through {@link OwnerMapper#formatMembershipLevel},
480	     * after decorating the members with their current household member counts, so the maximum
481	     * reflects the same effective (already-capped) level the API returns for those members.
482	     */
483	    private Integer computeMembershipLevelCap(Owner newOwner) {
484	        String householdId = newOwner.getHouseholdId();
485	        if (householdId == null) {
486	            return null;
487	        }
488	        List<Owner> members = ownerRepository.findAll().stream()
489	            .filter(existing -> existing != newOwner && existing.getId() != null)
490	            .filter(existing -> !existing.isDeleted())
491	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
492	            .collect(Collectors.toList());
493	        if (members.isEmpty()) {
494	            return null;
495	        }
496	        decorateWithHouseholdMemberCount(members, members);
497	        int maxLevel = members.stream()
498	            .mapToInt(member -> ownerMapper.formatMembershipLevel(member))
499	            .max()
500	            .getAsInt();
501	        return maxLevel + 1;
502	    }
503	
504	    @Override
505	    @Transactional(readOnly = true)
506	    public String householdIdFor(String lastName, String postcode) throws DataAccessException {
507	        // Version 2: the fixed 'V2' version tag is mixed into the hashed key, shifting every
508	        // household id away from its version-1 value while preserving which owners hash together
509	        // (same last name and postcode still share a household id).
510	        String key = Owner.IDENTITY_VERSION_TAG + "|" + normalizeHouseholdValue(lastName)
511	            + "|" + (postcode == null ? "" : postcode);
512	        return Sha256Hex.upperHexPrefix(key, 12);
513	    }
514	
515	    /**
516	     * Normalizes a household field (the last name) for the {@link #householdIdFor household id}
517	     * hash by trimming, collapsing runs of whitespace to a single space and lower-casing, so
518	     * differently cased or spaced but equivalent values yield the same household id.
519	     */
520	    private static String normalizeHouseholdValue(String value) {
521	        if (value == null) {
522	            return "";
523	        }
524	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
525	    }
526	
527	    /**
528	     * Populate each given owner's transient {@code householdMemberCount} with the current number of
529	     * owners that share its {@code householdId}. Owners without a household id are left at a count
530	     * of zero.
531	     *
532	     * <p>The household sizes are computed in a single pass over the owner table regardless of how
533	     * many owners are being decorated, so decorating a whole page does not re-scan per element.
534	     */
535	    private <T> T decorateWithHouseholdMemberCount(T result, Collection<Owner> owners) {
536	        if (!owners.isEmpty()) {
537	            Map<String, Long> sizeByHousehold = ownerRepository.findAll().stream()
538	                .filter(owner -> owner.getHouseholdId() != null)
539	                .collect(Collectors.groupingBy(Owner::getHouseholdId, Collectors.counting()));
540	            for (Owner owner : owners) {
541	                long size = owner.getHouseholdId() == null
542	                    ? 0L
543	                    : sizeByHousehold.getOrDefault(owner.getHouseholdId(), 0L);
544	                owner.setHouseholdMemberCount((int) size);
545	            }
546	        }
547	        return result;
548	    }
549	
550	    /**
551	     * Decorate a single (possibly {@code null}) owner with its household member count and return it.
552	     */
553	    private Owner decorateWithHouseholdMemberCount(Owner owner) {
554	        return decorateWithHouseholdMemberCount(owner, owner == null ? List.of() : List.of(owner));
555	    }
556	
557	    @Override
558	    @Transactional(readOnly = true)
559	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
560	        Collection<Owner> owners = ownerRepository.findByLastName(lastName);
561	        return decorateWithHouseholdMemberCount(owners, owners);
562	    }
563	
564	    @Override
565	    @Transactional(readOnly = true)
566	    public Collection<Visit> findVisitsByPetId(int petId) {
567	        return visitRepository.findByPetId(petId);
568	    }
569	
570	    @Override
571	    @Transactional(readOnly = true)
572	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
573	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
574	    }
575	
576	    private <T> T findEntityById(Supplier<T> supplier) {
577	        try {
578	            return supplier.get();
579	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
580	            // Just ignore not found exceptions for Jdbc/Jpa realization
581	            return null;
582	        }
583	    }
584	
585	}
